function validate([candies, k]) {
  if (!Array.isArray(candies) || candies.length < 1 || candies.length > 100000) return 'candies needs 1 to 100000 values.';
  if (candies.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each flavor is an integer from 1 to 100000.';
  if (!Number.isInteger(k) || k < 0 || k > candies.length) return 'k must be between 0 and candies.length.';
  return null;
}

