function shareCandies(candies, k) {
  const count = new Map();
  for (const flavor of candies) {
    count.set(flavor, (count.get(flavor) || 0) + 1);
  }
  let kept = count.size;
  for (let i = 0; i < k; i++) {
    count.set(candies[i], count.get(candies[i]) - 1);
    if (count.get(candies[i]) === 0) kept--;
  }
  let best = kept;
  for (let i = k; i < candies.length; i++) {
    const given = candies[i];
    count.set(given, count.get(given) - 1);
    if (count.get(given) === 0) kept--;
    const back = candies[i - k];
    if (count.get(back) === 0) kept++;
    count.set(back, count.get(back) + 1);
    best = Math.max(best, kept);
  }
  return best;
}

