function shareCandies(candies, k) {
  let answer = 0;
  for (let start = 0; start + k <= candies.length; start++) {
    const flavors = new Set();
    candies.forEach((flavor, index) => {
      if (index < start || index >= start + k) flavors.add(flavor);
    });
    answer = Math.max(answer, flavors.size);
  }
  return answer;
}

