function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 10);
    const top = int(1, 6);
    const candies = Array.from({ length: n }, () => int(1, top));
    const roll = rand();
    const k = roll < 0.15 ? 0 : roll < 0.25 ? n : int(0, n);
    return [candies, k];
  }
  const n = int(1800, 2000);
  const top = [30, 500, 2000, 100000][int(0, 3)];
  // Runs of one flavor make some blocks much better to give away than others.
  const candies = [];
  while (candies.length < n) {
    const flavor = int(1, top);
    const run = rand() < 0.3 ? int(2, 40) : 1;
    for (let r = 0; r < run && candies.length < n; r++) candies.push(flavor);
  }
  const k = rand() < 0.2 ? int(0, 20) : int(0, n);
  return [candies, k];
}
